<script setup>
import { computed, onMounted, onUnmounted, reactive, watch } from "vue";
import AppHeader from "./components/AppHeader.vue";
import Sidebar from "./components/Sidebar.vue";
import { createSnapshot, STATUS_LABELS } from "./data/projectSnapshot.js";

const VIEW_IDS = ["overview", "guide", "workflow", "rules", "engineering", "status", "directories"];
const STATUS_CLASS = { planned: "queued", in_progress: "active", blocked: "blocked", interrupted: "blocked", completed: "complete", cancelled: "muted", active: "active", queued: "queued", loading: "queued", untracked: "untracked", missing: "blocked", unknown: "muted" };
const state = reactive({ snapshot: null, activeView: readView(), selectedWorkflowId: null, selectedNodeId: null, theme: readTheme(), loading: false, error: "", syncState: "等待读取" });
const currentWorkflow = computed(() => state.snapshot?.workflows.find((item) => item.id === state.selectedWorkflowId) || state.snapshot?.workflows[0] || null);
const selectedNode = computed(() => currentWorkflow.value?.nodes.find((item) => item.id === state.selectedNodeId) || currentWorkflow.value?.nodes[0] || null);
const selectedStep = computed(() => state.snapshot?.steps.find((item) => item.id === selectedNode.value?.step) || null);
const healthPercent = computed(() => state.snapshot?.health.score || 0);
const projectWarnings = computed(() => state.snapshot?.warnings || []);

function readView() { const value = window.location.hash.slice(1); return VIEW_IDS.includes(value) ? value : "overview"; }
function readTheme() { try { return localStorage.getItem("easyvibe-view-theme") === "dark" ? "dark" : "light"; } catch { return "light"; } }
function setView(view) { state.activeView = VIEW_IDS.includes(view) ? view : "overview"; if (window.location.hash !== `#${state.activeView}`) window.history.replaceState(null, "", `#${state.activeView}`); }
function toggleTheme() { state.theme = state.theme === "dark" ? "light" : "dark"; try { localStorage.setItem("easyvibe-view-theme", state.theme); } catch {} }
async function loadProject() { if (state.loading) return; state.loading = true; state.syncState = "正在同步"; state.error = ""; try { const snapshot = await createSnapshot(); state.snapshot = snapshot; if (!snapshot.workflows.some((item) => item.id === state.selectedWorkflowId)) state.selectedWorkflowId = snapshot.defaultWorkflowId; state.syncState = `已同步 ${formatTime(snapshot.syncedAt)}`; } catch (error) { state.error = error.message; state.syncState = "读取失败"; } finally { state.loading = false; } }
function selectWorkflow(event) { state.selectedWorkflowId = event.target.value; state.selectedNodeId = null; }
function selectNode(nodeId) { state.selectedNodeId = nodeId; if (state.activeView !== "workflow") setView("workflow"); }
function selectWork(work) { if (work.workflow_id && state.snapshot.workflows.some((item) => item.id === work.workflow_id)) state.selectedWorkflowId = work.workflow_id; }
function statusLabel(value) { return STATUS_LABELS[value] || value || "未定义"; }
function statusClass(value) { return STATUS_CLASS[value] || "muted"; }
function stepName(stepId) { return state.snapshot?.steps.find((item) => item.id === stepId)?.name || stepId || "未定义 Step"; }
function nodeState(workflow, node) { if (!workflow || !node) return "untracked"; const works = state.snapshot.works.filter((work) => work.workflow_id === workflow.id); const tasks = works.flatMap((work) => work.tasks.filter((task) => task.step_id === node.step || task.node_id === node.id || task.id === node.id)); const current = works.filter((work) => work.current_task_id === node.id || work.tasks.some((task) => task.task_id === work.current_task_id && (task.step_id === node.step || task.node_id === node.id))); if (works.some((work) => ["blocked", "interrupted"].includes(work.status) && (current.includes(work) || !work.current_task_id)) || tasks.some((task) => ["blocked", "interrupted"].includes(task.status))) return "blocked"; if (tasks.length && tasks.every((task) => task.status === "completed" && task.result)) return "completed"; if (current.length || tasks.some((task) => ["in_progress", "active"].includes(task.status))) return "active"; if (tasks.some((task) => ["planned", "queued"].includes(task.status))) return "queued"; return tasks.length ? "active" : "untracked"; }
function formatTime(value) { if (!value) return "未记录"; const date = new Date(value); return Number.isNaN(date.getTime()) ? String(value) : new Intl.DateTimeFormat("zh-CN", { month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" }).format(date); }
function maxTaskCount() { return Math.max(...Object.values(state.snapshot?.status.tasksByStatus || {}), 1); }
function onHashChange() { setView(readView()); }

watch(() => state.theme, (theme) => { document.body.dataset.theme = theme; document.querySelector('meta[name="theme-color"]')?.setAttribute("content", theme === "dark" ? "#07111f" : "#f3f6fb"); }, { immediate: true });
let timer;
onMounted(() => { window.addEventListener("hashchange", onHashChange); timer = window.setInterval(loadProject, 20000); loadProject(); });
onUnmounted(() => { window.removeEventListener("hashchange", onHashChange); window.clearInterval(timer); });
</script>

<template>
  <AppHeader :theme="state.theme" :loading="state.loading" :sync-state="state.syncState" @toggle-theme="toggleTheme" @refresh="loadProject" />
  <main>
    <div v-if="state.error && !state.snapshot" class="error-banner"><strong>项目数据无法读取</strong><span>{{ state.error }}</span></div>
    <div v-else-if="!state.snapshot" class="welcome-screen"><div class="welcome-mark">EV</div><p class="kicker">PROJECT VISIBILITY</p><h2>正在读取项目状态</h2><p class="welcome-copy">工作台只读项目文件，不依赖业务后端。</p></div>
    <div v-else class="workspace-layout">
      <Sidebar :active-view="state.activeView" @select="setView" />
      <div class="workspace-main">
        <div v-if="state.error || projectWarnings.length" class="warning-banner"><strong>{{ state.error ? '本次同步未完整完成' : '部分项目数据暂不可用' }}</strong><span>{{ state.error || '工作台其余内容仍可正常使用，缺失内容会在文件准备完成后自动恢复。' }}</span><details v-if="projectWarnings.length"><summary>查看 {{ projectWarnings.length }} 条读取提示</summary><ul><li v-for="warning in projectWarnings" :key="warning">{{ warning }}</li></ul></details></div>
        <section v-if="state.activeView === 'overview'" class="view-content"><div class="content-grid"><div class="main-column"><section class="panel"><div class="panel-header"><div><p class="kicker">DELIVERY FLOW</p><h2>交付流程</h2></div><label class="compact-select">当前工作流<select :value="state.selectedWorkflowId" @change="selectWorkflow"><option v-for="workflow in state.snapshot.workflows" :key="workflow.id" :value="workflow.id">{{ workflow.name }}</option></select></label></div><p class="flow-meta">{{ currentWorkflow?.description || "项目尚未定义可展示的工作流" }}</p><div v-if="currentWorkflow" class="flow-grid"><template v-for="(node, index) in currentWorkflow.nodes" :key="node.id"><button class="flow-stage" :class="nodeState(currentWorkflow, node)" type="button" @click="selectNode(node.id)"><div class="flow-stage-top"><span class="flow-number">{{ String(index + 1).padStart(2, '0') }}</span><span class="status" :class="`status-${statusClass(nodeState(currentWorkflow, node))}`">{{ statusLabel(nodeState(currentWorkflow, node)) }}</span></div><strong>{{ stepName(node.step) }}</strong><small>{{ node.step }}</small><em v-if="node.id === currentWorkflow.entry">入口</em></button></template></div><div v-else class="empty-inline">没有可用工作流</div></section><section class="panel"><div class="panel-header"><div><p class="kicker">CURRENT WORK</p><h2>当前工作</h2></div><span class="panel-count">{{ state.snapshot.works.length }} 项</span></div><div v-if="state.snapshot.works.length" class="work-list"><button v-for="work in state.snapshot.works" :key="work.work_id" class="work-row" type="button" @click="selectWork(work)"><span class="work-primary"><b>{{ work.work_id || '未命名' }}</b><strong>{{ work.title || '未命名工作' }}</strong><small>{{ work.workflow_id || '未指定工作流' }}</small></span><span class="status" :class="`status-${statusClass(work.status)}`">{{ statusLabel(work.status) }}</span><span class="work-progress"><i :style="{ width: `${work.progress.percent}%` }"></i>{{ work.progress.total ? `${work.progress.completed}/${work.progress.total}` : '未跟踪' }}</span><span>{{ work.current_task_id || '未指定' }}</span><span>{{ work.next_action || '未指定下一步' }}</span></button></div><div v-else class="empty-inline"><strong>暂无主工作记录</strong><span>status/works.csv 尚未登记工作</span></div></section></div><aside class="side-column"><section class="panel"><div class="panel-header"><div><p class="kicker">GOVERNANCE</p><h2>规则与安全</h2></div><span class="safety-level">{{ state.snapshot.safety.defaultLevel }}</span></div><div class="governance-list"><div v-for="rule in state.snapshot.governance" :key="rule.id" class="governance-row"><div><strong>{{ rule.name }}</strong><small>{{ rule.id }}</small></div><span>{{ rule.ruleCount }} 条规则</span></div></div><div class="safety-summary"><span>安全原则 <b>{{ state.snapshot.safety.principleCount }}</b></span><span>资源索引 <b>{{ state.snapshot.safety.resourceCount }}</b></span></div><div class="subsection-label">工程实现规范</div><div class="spec-mini-list"><div v-for="spec in state.snapshot.engineeringSpecs.slice(1)" :key="spec.id"><strong>{{ spec.name }}</strong><small>{{ spec.ruleCount }} 条 · {{ spec.filePath }}</small></div></div></section></aside></div><section class="metric-grid overview-signals"><article class="metric metric-health"><div class="metric-symbol">◎</div><div><p class="metric-label">结构健康</p><strong>{{ healthPercent }}%</strong><p class="metric-detail">{{ state.snapshot.health.presentCount }}/{{ state.snapshot.health.expectedCount }} 个核心项存在</p></div></article><article class="metric metric-progress"><div class="metric-symbol">↗</div><div><p class="metric-label">开发进度</p><strong>{{ state.snapshot.progress.totalTasks ? `${state.snapshot.progress.percent}%` : "尚未开始" }}</strong><p class="metric-detail">{{ state.snapshot.progress.totalTasks ? `${state.snapshot.progress.completedTasks}/${state.snapshot.progress.totalTasks} 个子任务已完成` : "暂无子任务记录" }}</p></div></article><article class="metric metric-work"><div class="metric-symbol">▣</div><div><p class="metric-label">活跃工作</p><strong>{{ state.snapshot.status.activeWorkCount }}</strong><p class="metric-detail">{{ state.snapshot.status.activeWorkCount ? "仍有未结束主工作" : "没有未结束主工作" }}</p></div></article><article class="metric metric-risk"><div class="metric-symbol">!</div><div><p class="metric-label">未关闭 Bug</p><strong>{{ state.snapshot.bugs.openCount }}</strong><p class="metric-detail">{{ state.snapshot.bugs.openCount ? "需要关注的未关闭事项" : "当前没有待处理 Bug" }}</p></div></article></section></section>

        <section v-else-if="state.activeView === 'guide'" class="view-content"><div class="section-intro"><div><p class="kicker">ENTRY GUIDE</p><h2>接入路径</h2><p>根据 guide/README.md 的读取顺序，呈现 Agent 进入项目时的上下文路径。</p></div><span class="source-pill">guide/README.md</span></div><div class="two-column"><section class="panel"><div class="panel-header"><h2>推荐读取顺序</h2><span class="panel-count">{{ state.snapshot.guide.path.length }} 项</span></div><div class="guide-list"><div v-for="(item, index) in state.snapshot.guide.path" :key="item.path" class="guide-item" :class="{ missing: !item.exists }"><b>{{ String(index + 1).padStart(2, '0') }}</b><div><strong>{{ item.label }}</strong><small>{{ item.path }}</small></div><span>{{ item.exists ? '可读取' : '缺失' }}</span></div></div></section><section class="panel"><div class="panel-header"><h2>权威入口</h2><span class="panel-count">{{ state.snapshot.guide.authority.length }} 项</span></div><div class="authority-list"><div v-for="item in state.snapshot.guide.authority" :key="item.path" class="authority-row" :class="{ missing: !item.exists }"><div><strong>{{ item.label }}</strong><small>{{ item.path }}</small></div><span>{{ item.exists ? '权威入口' : '缺失' }}</span></div></div></section></div></section>

        <section v-else-if="state.activeView === 'workflow'" class="view-content"><div class="section-intro"><div><p class="kicker">WORKFLOW LOGIC</p><h2>交付流程图</h2><p>节点状态来自当前工作与子任务，转换条件来自工作流定义。</p></div><label class="compact-select">选择工作流<select :value="state.selectedWorkflowId" @change="selectWorkflow"><option v-for="workflow in state.snapshot.workflows" :key="workflow.id" :value="workflow.id">{{ workflow.name }}</option></select></label></div><div class="workflow-layout"><section class="panel"><div class="flow-grid detailed-flow"><template v-for="(node, index) in currentWorkflow?.nodes || []" :key="node.id"><button class="flow-stage" :class="nodeState(currentWorkflow, node)" type="button" @click="selectNode(node.id)"><div class="flow-stage-top"><span class="flow-number">{{ String(index + 1).padStart(2, '0') }}</span><span class="status" :class="`status-${statusClass(nodeState(currentWorkflow, node))}`">{{ statusLabel(nodeState(currentWorkflow, node)) }}</span></div><strong>{{ stepName(node.step) }}</strong><small>{{ node.step }}</small></button></template></div><div class="panel-header transition-heading"><h2>转换条件</h2><span class="panel-count">{{ currentWorkflow?.transitions.length || 0 }} 条</span></div><div class="transition-list"><div v-for="(transition, index) in currentWorkflow?.transitions || []" :key="`${transition.from}-${transition.to}-${index}`" class="transition-row"><b>{{ String(index + 1).padStart(2, '0') }}</b><strong>{{ transition.from }} → {{ transition.to }}</strong><small>{{ transition.when || '无条件转换' }}</small></div></div></section><aside class="panel inspector"><p class="kicker">NODE INSPECTOR</p><h2>{{ selectedStep?.name || '选择一个节点' }}</h2><p class="muted">{{ selectedStep?.description || '查看该 Step 的风险级别、路径权限和规则覆盖。' }}</p><div v-if="selectedStep" class="inspector-details"><div><span>节点状态</span><strong>{{ statusLabel(nodeState(currentWorkflow, selectedNode)) }}</strong></div><div><span>Step ID</span><code>{{ selectedStep.id }}</code></div><div><span>风险级别</span><strong>{{ selectedStep.safety?.riskLevel || '未定义' }}</strong></div><div><span>规则数量</span><strong>{{ selectedStep.spec.ruleCount }}</strong></div><div><span>允许读取</span><code>{{ selectedStep.paths?.read?.join(' · ') || '无' }}</code></div><div><span>允许写入</span><code>{{ selectedStep.paths?.write?.join(' · ') || '无' }}</code></div></div></aside></div></section>

        <section v-else-if="state.activeView === 'rules'" class="view-content"><div class="section-intro"><div><p class="kicker">RULE SYSTEM</p><h2>规则治理</h2><p>规则按项目优先级、工程领域和当前工作流 Step 作用域组织。</p></div><span class="source-pill">spec/ · deploy/safe.json</span></div><div class="precedence-bar"><div class="precedence-step"><span>01</span><strong>对话规则</strong><small>用户当前指令</small></div><i aria-hidden="true">→</i><div class="precedence-step"><span>02</span><strong>项目总规约</strong><small>项目基础边界</small></div><i aria-hidden="true">→</i><div class="precedence-step"><span>03</span><strong>工程实现规范</strong><small>领域实现格式</small></div><i aria-hidden="true">→</i><div class="precedence-step"><span>04</span><strong>Step 规约</strong><small>当前流程范围</small></div></div><div class="rules-layout"><section class="panel"><div class="panel-header"><h2>生效规约</h2><span class="panel-count">{{ state.snapshot.governance.reduce((sum, item) => sum + item.ruleCount, 0) }} 条规则</span></div><div class="rule-tree"><div v-for="rule in state.snapshot.governance" :key="rule.id" class="rule-group"><strong>{{ rule.name }}</strong><small>{{ rule.filePath }} · {{ rule.ruleCount }} 条规则</small></div><div class="rule-group engineering-group"><strong>工程实现规范</strong><small>spec/custom/engineering/ · {{ state.snapshot.engineeringSpecs.length }} 个规范文件</small><div class="engineering-grid"><div v-for="spec in state.snapshot.engineeringSpecs" :key="spec.id"><b>{{ spec.name }}</b><span>{{ spec.ruleCount }} 条 · {{ spec.filePath }}</span></div></div></div></div></section><aside class="panel"><div class="panel-header"><h2>安全边界</h2><span class="safety-level">{{ state.snapshot.safety.defaultLevel }}</span></div><p class="muted">{{ state.snapshot.safety.principleCount }} 条安全原则，{{ state.snapshot.safety.resourceCount }} 个资源索引。</p><div class="safety-list"><div v-for="principle in state.snapshot.safety.principles" :key="principle.id"><strong>{{ principle.name }}</strong><small>{{ principle.requirement }}</small></div></div></aside></div></section>
        <section v-else-if="state.activeView === 'engineering'" class="view-content"><div class="section-intro"><div><p class="kicker">ENGINEERING SYSTEM</p><h2>工程规范</h2><p>按领域组织可扩展的实现格式，帮助 Agent 和团队保持一致，但不预设框架、语言或数据库产品。</p></div><span class="source-pill">spec/custom/engineering/</span></div><div class="engineering-overview"><section class="panel engineering-intro-panel"><div class="panel-header"><div><p class="kicker">FORMAT FIRST</p><h2>只定义格式</h2></div><span class="status status-complete">已接入</span></div><p class="muted">每份规范都提供用途、适用范围、规则字段、验证方式和证据要求。具体技术选型由项目决策和当前需求决定。</p><div class="engineering-principles"><span>可组合</span><span>可验证</span><span>不锁定技术</span></div></section><section class="panel"><div class="panel-header"><div><p class="kicker">SPEC FILES</p><h2>领域文件</h2></div><span class="panel-count">{{ state.snapshot.engineeringSpecs.length }} 个文件</span></div><div class="engineering-file-list"><article v-for="spec in state.snapshot.engineeringSpecs" :key="spec.id" class="engineering-file-card" :class="{ missing: !spec.exists }"><div class="engineering-file-head"><span class="directory-icon">{{ spec.exists ? '✓' : '!' }}</span><div><strong>{{ spec.name }}</strong><small>{{ spec.relativePath || spec.filePath }}</small></div><span class="status" :class="`status-${spec.exists ? 'complete' : 'blocked'}`">{{ spec.exists ? '生效' : '缺失' }}</span></div><p>{{ spec.summary || '该领域规范尚未填写摘要。' }}</p><div class="engineering-file-meta"><span>{{ spec.ruleCount }} 条格式规则</span><code>{{ spec.id }}</code></div></article></div></section></div><div class="directory-note"><strong>加载方式</strong><span>先读 engineering/README.md，再按变更范围读取 ui.md、backend.md 或 database.md；也可使用 <code>easyvibe specs</code> 查询。</span></div></section>

        <section v-else-if="state.activeView === 'status'" class="view-content"><div class="section-intro"><div><p class="kicker">WORK STATUS</p><h2>工作状态</h2><p>主工作承载交付目标，子任务记录当前节点、依赖、修改范围和验证结果。</p></div><span class="source-pill">status/works.csv</span></div><div class="status-layout"><section class="panel"><div class="panel-header"><h2>进度信号</h2><span class="panel-count">{{ state.snapshot.status.taskCount }} 项任务</span></div><div v-if="Object.keys(state.snapshot.status.tasksByStatus).length" class="status-bars"><div v-for="(count, status) in state.snapshot.status.tasksByStatus" :key="status" class="status-bar-row"><span>{{ statusLabel(status) }}</span><i><b :class="`bar-${statusClass(status)}`" :style="{ width: `${Math.max(8, count / maxTaskCount() * 100)}%` }"></b></i><strong>{{ count }}</strong></div></div><div v-else class="empty-inline">暂无子任务状态</div><div class="verification-callout">{{ state.snapshot.status.unverifiedCompletedTaskCount ? `${state.snapshot.status.unverifiedCompletedTaskCount} 个完成项缺少验证结果` : '完成项验证完整' }}</div></section><section class="panel"><div class="panel-header"><h2>主工作与子任务</h2><span class="panel-count">{{ state.snapshot.status.workCount }} 项工作</span></div><div v-if="state.snapshot.works.length" class="status-work-list"><article v-for="work in state.snapshot.works" :key="work.work_id" class="status-work-card"><div class="status-work-head"><div><b>{{ work.work_id }}</b><h3>{{ work.title }}</h3></div><span class="status" :class="`status-${statusClass(work.status)}`">{{ statusLabel(work.status) }}</span></div><p>{{ work.next_action || '未指定下一步' }}</p><div v-for="task in work.tasks" :key="task.task_id" class="task-row"><span>{{ task.status === 'completed' ? '✓' : '·' }}</span><strong>{{ task.task_id }} · {{ task.title }}</strong><small>{{ task.step_id }} · {{ statusLabel(task.status) }}</small></div></article></div><div v-else class="empty-inline">暂无主工作记录</div></section></div></section>

        <section v-else class="view-content"><div class="section-intro"><div><p class="kicker">DIRECTORY MAP</p><h2>项目目录</h2><p>目录型内容只展示职责、存在性和规模，不进入文件正文。</p></div><span class="source-pill">{{ state.snapshot.structure.filter((item) => item.exists).length }}/{{ state.snapshot.structure.length }} 个目录已就绪</span></div><div class="directory-grid"><article v-for="directory in state.snapshot.structure" :key="directory.id" class="directory-card" :class="{ missing: !directory.exists }"><div class="directory-card-top"><span class="directory-icon">{{ directory.exists ? '✓' : '!' }}</span><strong>{{ directory.label }}</strong><span class="status" :class="`status-${directory.exists ? 'complete' : 'blocked'}`">{{ directory.exists ? '已就绪' : '缺失' }}</span></div><p>{{ directory.description }}</p><div class="directory-card-meta"><span>{{ directory.fileCount }} 个文件</span><code>{{ directory.id }}/</code></div></article></div><div class="directory-note"><strong>展示边界</strong><span>文档、部署、数据、命令、Agent 和工作台作为项目模块观察；工程规范目录位于 spec/custom/engineering/。</span></div></section>
      </div>
    </div>
  </main>
</template>
